import{_ as o,r as t,o as l,c as p,e as a,a as r,s as d}from"./chunks/framework.CXcwiNg-.js";const y=JSON.parse('{"title":"Balloon Selector Field - October CMS - 3.x","titleTemplate":false,"description":"Form Field","frontmatter":{"subtitle":"Form Field","shortname":"Balloon Selector"},"headers":[{"level":4,"title":"See Also","slug":"see-also","link":"#see-also","children":[]}],"relativePath":"3.x/element/form/field-balloon.md","filePath":"3.x/element/form/field-balloon.md"}'),c={name:"3.x/element/form/field-balloon.md"};function i(u,e,m,k,h,f){const n=t("pre-heading"),s=t("post-heading");return l(),p("div",null,[a(n),e[0]||(e[0]=r("h1",null,"Balloon Selector Field",-1)),a(s),e[1]||(e[1]=d(`<p>The <code>balloon-selector</code> field renders a list, where only one item can be selected at a time. Balloon selectors support the same methods for defining the options as the <a href="./field-dropdown.html">dropdown field type</a>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">gender</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> balloon<span class="token punctuation">-</span>selector
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Gender
    <span class="token key atrule">options</span><span class="token punctuation">:</span>
        <span class="token key atrule">female</span><span class="token punctuation">:</span> Female
        <span class="token key atrule">male</span><span class="token punctuation">:</span> Male
</code></pre></div><p>The following <a href="./../form-fields.html">field properties</a> are commonly used.</p><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><strong>label</strong></td><td>a name when displaying the form field to the user.</td></tr><tr><td><strong>default</strong></td><td>a default value to use for new records.</td></tr><tr><td><strong>comment</strong></td><td>places a descriptive comment below the field.</td></tr><tr><td><strong>options</strong></td><td>available options for the dropdown, as an array.</td></tr><tr><td><strong>optionsMethod</strong></td><td>take options from a method defined on the model or as a static method, eg <code>Class::method</code>.</td></tr><tr><td><strong>allowEmpty</strong></td><td>allows the selection to be unset by clicking on the active item, default: <code>false</code>.</td></tr></tbody></table></div><p>You may use the <code>default</code> property to set a default value, where the value is the key of the option.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">gender</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> balloon<span class="token punctuation">-</span>selector
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Gender
    <span class="token key atrule">default</span><span class="token punctuation">:</span> female
</code></pre></div><p>Set the <code>allowEmpty</code> property to <strong>true</strong> to allow the user to set an empty value by unselecting the active item.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">gender</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> balloon<span class="token punctuation">-</span>selector
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Gender
    <span class="token key atrule">allowEmpty</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>
</code></pre></div><h4 id="see-also"><a href="#see-also" class="header-anchor">#</a> See Also</h4><div class="custom-block also"><ul><li><a href="./field-dropdown.html">Dropdown Form Field</a></li></ul></div>`,10))])}const b=o(c,[["render",i]]);export{y as __pageData,b as default};
